var scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).ToArray();
var rs=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);
var result=new{playing=UnityEditor.EditorApplication.isPlaying,scenes=scenes.Select(s=>new{s.name,s.path,s.isDirty}),roots=scenes.SelectMany(s=>s.GetRootGameObjects()).Select(g=>g.name),near=rs.Where(r=>r.bounds.center.x>24&&r.bounds.center.x<44&&r.bounds.center.z>34&&r.bounds.center.z<42).Take(150).Select(r=>new{r.name,path=UnityEditor.AnimationUtility.CalculateTransformPath(r.transform,null),center=r.bounds.center.ToString(),size=r.bounds.size.ToString(),enabled=r.enabled,materials=r.sharedMaterials.Select(m=>m==null?"NULL":m.name).Distinct()}),models=UnityEditor.AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Art/Environments/TownProps02"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath)};
var json=Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented);System.IO.File.WriteAllText("D:/Demo/ArtWork/TownFinish62/Inspection.json",json);return json;
